insert into public.characters (id, name, title, tagline, quote, description, edition, edition_label, pack, rarity, art, attributes, wardrobe_slots, status, price, supply, limit_per_wallet, published, sort_order) values ('yeti', 'Yeti', 'Fuchey Yeti', 'Basic Companion', 'Your wallet just got a little friend.', 'The original Fuchey. A soft, frosty little desk companion that reacts to your wallet — happy when tokens land, curious when something new arrives, sleepy when the chain goes quiet.', 'companion', 'Basic', 'wild', 'common', '{"kind":"character","image":"yeti"}'::jsonb, '[{"trait_type":"Character","value":"Yeti"},{"trait_type":"Edition","value":"Basic"},{"trait_type":"Mood","value":"Friendly"},{"trait_type":"Habitat","value":"Glacier"}]'::jsonb, array['hat', 'headwear', 'outfit', 'accessory', 'backpack', 'held', 'special']::public.wearable_slot[], 'available', 0, 10000, 1, true, 0) on conflict (id) do nothing;
